import java.util.*;

public class Collections1 {
    public static void main(String[] args) {
        List<String> names = new ArrayList<>();
        names.add("Asha");
        names.add("Ravi");
        System.out.println(names.get(0));       // Asha — indexed access

        Set<Integer> unique = new HashSet<>(List.of(3, 1, 3, 2));
        System.out.println(unique.size());        // 3 — duplicate discarded

        Set<Integer> sorted = new TreeSet<>(List.of(3, 1, 2));
        System.out.println(sorted);                // [1, 2, 3] — always sorted
    }
}
